<script lang="ts">
  import { page } from '$app/state'; import { createApiClient } from '$lib/api/client'; import { goto } from '$app/navigation';
  let id = $derived(page.params.id); let error = $state(''); let saving = $state(false);
  async function save(event: SubmitEvent) { event.preventDefault(); saving=true; error=''; const f=new FormData(event.currentTarget as HTMLFormElement); try { await createApiClient().put(`/api/v1/players/${id}`, { headers:{'content-type':'application/json'}, body:JSON.stringify({coins:Number(f.get('coins')),luck:Number(f.get('luck')),alive:f.get('alive')==='true',alignment:f.get('alignment'),item_limit:Number(f.get('item_limit')),role:f.get('role')}) }); await goto(`/players/${id}`); } catch(e) { error=e instanceof Error?e.message:'Could not save player'; } finally { saving=false; } }
</script>
<svelte:head><title>Edit player {id} | Betrayal Admin</title></svelte:head><main class="min-h-screen bg-slate-950 p-6 text-slate-100"><h1 class="mx-auto max-w-xl text-3xl">Edit player {id}</h1>{#if error}<p role="alert" class="mx-auto max-w-xl py-4 text-red-300">{error}</p>{/if}<form onsubmit={save} class="mx-auto mt-8 max-w-xl space-y-4 border border-slate-700 p-6"><label>Role<input name="role" required /></label><label>Coins<input name="coins" type="number" required /></label><label>Luck<input name="luck" type="number" required /></label><label>Item limit<input name="item_limit" type="number" min="0" required /></label><label>Alignment<select name="alignment"><option>GOOD</option><option>NEUTRAL</option><option>EVIL</option></select></label><label>Alive<select name="alive"><option value="true">Alive</option><option value="false">Dead</option></select></label><button disabled={saving}>{saving?'Saving…':'Save player'}</button></form></main>
